/**
 * @wopr-network/plugin-types — canonical type definitions for WOPR plugins.
 *
 * This is the single source of truth for all plugin-facing types.
 * Plugins should import from here instead of defining their own copies.
 *
 * Usage (once published as @wopr-network/plugin-types):
 *   import type { WOPRPlugin, WOPRPluginContext, ConfigSchema } from "@wopr-network/plugin-types";
 *
 * Usage (from within the wopr monorepo):
 *   import type { WOPRPlugin, WOPRPluginContext, ConfigSchema } from "../plugin-types/index.js";
 */
export type { A2AServerConfig, A2AToolDefinition, A2AToolResult } from "./a2a.js";
export type { ChannelAdapter, ChannelCommand, ChannelCommandContext, ChannelMessageContext, ChannelMessageParser, ChannelProvider, ChannelRef, } from "./channel.js";
export type { ConfigField, ConfigSchema, SetupFlowType } from "./config.js";
export type { AgentIdentity, MultimodalMessage, PluginInjectOptions, PluginLogger, PluginUiComponentProps, StreamCallback, StreamMessage, UiComponentExtension, UserProfile, WebUiExtension, WOPRPluginContext, } from "./context.js";
export type { ContextPart, ContextProvider, MessageInfo } from "./context-provider.js";
export type { ChannelMessageEvent, ChannelMessageHandler, ChannelSendEvent, ConfigChangeEvent, EventHandler, HookOptions, MemoryFileChange, MemoryFilesChangedEvent, MemorySearchEvent, MessageIncomingHandler, MessageOutgoingHandler, MutableHookEvent, PluginErrorEvent, PluginInitEvent, SessionCreateEvent, SessionCreateHandler, SessionDestroyEvent, SessionDestroyHandler, SessionInjectEvent, SessionResponseChunkEvent, SessionResponseEvent, SystemShutdownEvent, WOPREvent, WOPREventBus, WOPREventMap, WOPRHookManager, } from "./events.js";
export type { InstallMethod, ManifestProviderEntry, NetworkRequirements, PluginCapability, PluginCategory, PluginLifecycle, PluginManifest, PluginRequirements, SetupStep, StorageRequirements, } from "./manifest.js";
export type { Filter, FilterCondition, FilterOperator, OrderDirection, PluginSchema, QueryBuilder, Repository, StorageApi, TableIndex, TableSchema, } from "./storage.js";
export type { InstalledPlugin, PluginCommand, PluginRegistryEntry, WOPRPlugin } from "./plugin.js";
